import { View } from 'react-native'
import { ProjectCreationBlocker } from './ProjectCreationBlocker'
import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { useSafeAreaInsets } from 'react-native-safe-area-context'

export const ProjectCreationBlockerContainer = ({
	hasReachedChatCreditsLimit,
	hasSpeechPermission
}: {
	hasReachedChatCreditsLimit: boolean
	hasSpeechPermission: boolean
}) => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()

	return (
		<View
			style={[
				styles.container(
					theme,
					hasReachedChatCreditsLimit && !hasSpeechPermission
				),
				{ marginBottom: insets.bottom }
			]}
		>
			<ProjectCreationBlocker
				hasReachedChatCreditsLimit={hasReachedChatCreditsLimit}
				hasSpeechPermission={hasSpeechPermission}
			/>
		</View>
	)
}

const styles = defineStyles({
	container: (theme: Theme, withBuffer: boolean) => ({
		height: withBuffer ? 190 : 170,
		backgroundColor: colors[theme].gray[50],
		borderRadius: 20,
		paddingVertical: 20,
		marginHorizontal: 20,
		zIndex: 2
	})
})
